const legacyReverse=new Map();for(const [loc,map] of Object.entries(LEGACY))for(const [src,val] of Object.entries(map)){legacyReverse.set(src.trim().toLowerCase(),src);legacyReverse.set(String(val).trim().toLowerCase(),src)}
function legacyText(s){const raw=String(s||'').trim(),src=legacyReverse.get(raw.toLowerCase());if(src)return LEGACY[current]?.[src]??LEGACY['id-ID'][src]??raw;const m=raw.match(/^(?:MEJA|Meja|Table(?: Number)?|الطاولة)\s+(\d+)$/i);if(m)return t('receipt.table')+' '+m[1];return''}
function canonical(v){v=String(v||'').trim();if(LOCALES.includes(v))return v;const p=v.toLowerCase().split('-')[0],x=LOCALES.find(l=>l.toLowerCase().split('-')[0]===p);return x||'id-ID'}
