function routeKey(el){const d=el?.dataset;if(!d)return'';if(d.main==='general')return'nav.general';if(d.main==='public')return'nav.public';if(d.main==='admin')return'nav.admin';if(d.main==='kds')return'nav.kds';if(d.main==='database')return'nav.database';if(d.settingsMain!==undefined||d.settingsMainV29!==undefined||d.settingsMainV2!==undefined)return'nav.settings';if(d.act==='start'||d.act==='verify_start')return'action.process';if(d.act==='ready')return'action.ready';if(d.act==='complete')return'action.handover';if(d.act==='reject_payment')return'action.reject';return''}
const textKey=s=>reverse.get(String(s||'').trim().toLowerCase())||'';
const SUB_KEYS={'Bahasa':'nav.language','Transaksi dan Pembayaran':'nav.transactions','Printer Thermal':'nav.printer','Riwayat Pesanan':'database.history','Sinkronisasi':'database.sync','Spreadsheet':'database.spreadsheet'};
let resolveCache=new Map();
function resolvedText(s){const raw=String(s||'').trim();if(!raw)return'';const ck=current+'\u0000'+raw;if(resolveCache.has(ck))return resolveCache.get(ck);const k=textKey(raw),v=k?t(k):legacyText(raw);resolveCache.set(ck,v||'');return v||''}
