function translateNode(node){if(!node)return false;let changed=false;if(node.nodeType===3){const parent=node.parentElement;if(!parent||/^(SCRIPT|STYLE|CODE|PRE|TEXTAREA)$/i.test(parent.tagName))return false;const raw=String(node.nodeValue||''),trim=raw.trim();if(!trim)return false;const next=resolvedText(trim);if(next){const lead=raw.match(/^\s*/)?.[0]||'',tail=raw.match(/\s*$/)?.[0]||'';changed=setNodeText(node,lead+next+tail)||changed}return changed}if(node.nodeType!==1)return false;const el=node,d=el.dataset||{},explicit=d.i18n||routeKey(el);if(explicit)changed=setElementText(el,t(explicit))||changed;for(const a of ['placeholder','title','aria-label']){const v=el.getAttribute?.(a);if(!v)continue;const next=resolvedText(v);if(next)changed=setAttr(el,a,next)||changed}const raw=String(d.sub||d.settingsSub||d.settingsSubV29||d.settingsSubV2||'');if(raw&&SUB_KEYS[raw])changed=setElementText(el,t(SUB_KEYS[raw]))||changed;return changed}
function syncMeta(){const root=document.documentElement,lang=current.split('-')[0],dir=current==='ar-SA'?'rtl':'ltr';if(root.dataset.sdbLanguage!==current)root.dataset.sdbLanguage=current;if(root.lang!==lang)root.lang=lang;if(root.dir!==dir)root.dir=dir}
function translateSubtree(root=document,emit=false){if(!root)return false;let changed=translateNode(root);if(root.nodeType===1||root.nodeType===9||root.nodeType===11){const w=document.createTreeWalker(root,NodeFilter.SHOW_ELEMENT|NodeFilter.SHOW_TEXT);let n;while((n=w.nextNode()))changed=translateNode(n)||changed}syncMeta();if(emit)document.dispatchEvent(new CustomEvent('sdb:i18n-applied',{detail:{locale:current}}));return changed}
