const locale=()=>current;
let queued=false;const pendingRoots=new Set();
function queueRoot(root){if(!root)return;pendingRoots.add(root);if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;const roots=[...pendingRoots];pendingRoots.clear();const minimal=roots.filter((r,i)=>!roots.some((p,j)=>i!==j&&p?.nodeType===1&&r!==p&&p.contains?.(r)));let changed=false;for(const root of minimal){if(root===document||root?.isConnected)changed=translateSubtree(root,false)||changed}if(changed)document.dispatchEvent(new CustomEvent('sdb:i18n-applied',{detail:{locale:current}}))})}
